import {DynamicDrawUsage} from 'three';

export function prepareMeshAttributeVisual(root){const meshes=root.children.filter(child=>child.isMesh);if(meshes.length!==1)return null;const mesh=meshes[0],geometry=mesh.geometry,attributes={};for(const key of ['position','normal','uv','uv1','color']){attributes[key]=geometry.attributes[key];attributes[key]?.setUsage(DynamicDrawUsage);}return{mesh,geometry,attributes,index:geometry.index};}
export function updateMeshAttributeVisual(root,previous,data,state,dirty){
 if(!state||state.mesh.parent!==root||state.mesh.geometry!==state.geometry||previous.vertices.length!==data.vertices.length||previous.indices.length!==data.indices.length||!!previous.uvs1!==!!data.uvs1||!!previous.colors!==!!data.colors||previous.normals!==undefined&&data.normals===undefined)return false;const geometry=state.geometry,count=data.vertices.length;if(geometry.index!==state.index||Object.keys(state.attributes).some(key=>geometry.attributes[key]!==state.attributes[key])||geometry.attributes.tangent||Object.keys(geometry.morphAttributes||{}).some(key=>geometry.morphAttributes[key]?.length))return false;
 // Admit every structural/pointer/layout requirement before writing a buffer.
 const positions=geometry.attributes.position;if(!geometry.index?.array||geometry.index.itemSize!==1||geometry.index.count!==data.indices.length||positions?.count!==count||positions.itemSize!==3||positions.isInterleavedBufferAttribute||!positions.array)return false;for(let i=0;i<data.indices.length;i++)if(previous.indices[i]!==data.indices[i]||geometry.index.array[i]!==data.indices[i])return false;for(let i=0;i<count;i++)for(let axis=0;axis<3;axis++)if(previous.vertices[i][axis]!==data.vertices[i][axis]||positions.array[i*3+axis]!==Math.fround(data.vertices[i][axis]))return false;
 const channels=[['normal',data.normals,3],['uv',data.uvs,2],['uv1',data.uvs1,2],['color',data.colors,3]],changes=[];for(const [name,values,size]of channels){if(!values)continue;const attribute=geometry.attributes[name];if(!attribute||attribute.isInterleavedBufferAttribute||attribute.count!==count||attribute.itemSize!==size)return false;const ids=[];for(let i=0;i<count;i++){let changed=false;for(let k=0;k<size;k++)if(attribute.array[i*size+k]!==Math.fround(values[i][k])){changed=true;break;}if(changed)ids.push(i);}changes.push({name,values,size,attribute,ids});}
 const diagnostic={kind:'mesh',geometryReused:true,indexRebuilt:false,positionWrites:0,normalWrites:0,uvWrites:0,uv1Writes:0,colorWrites:0,vertices:count};for(const {name,values,size,attribute,ids}of changes){for(const id of ids)for(let k=0;k<size;k++)attribute.array[id*size+k]=values[id][k];dirty(attribute,ids);diagnostic[name==='normal'?'normalWrites':name==='color'?'colorWrites':name==='uv1'?'uv1Writes':'uvWrites']=ids.length;}root.userData.worldUpdate=diagnostic;return true;
}
export const meshAttributeUpdateContract={trigger:'existing immutable mesh document update with unchanged positions/indices and UV/color layout',retained:'same geometry/material/index/position/normal/UV/color buffer objects; float32-different rows only, existing <=64 accumulated dirty ranges and one attribute version update, unchanged channels untouched',fallback:'Position/index/count/UV1 or color presence changes, authored normal removal, replaced/missing/interleaved layouts, tangents or morph attributes return false before any writes; existing load/dispose path handles them.',lifetime:'Prepared raw world-mesh geometry pointer only; no global actor scan or new render-frame loop. Full document validation and topology/position/channel comparisons remain; no worst-case or whole-scene speed claim.',verification:'Headless actual Three attribute identity/version/ranges against fresh geometry; GPU/DX/WebGL/WebGPU upload pixels/device remain separate.'};
